WITH remaining_keys AS (SELECT product_id FROM store_sales EXCEPT ALL SELECT product_id FROM store_sales WHERE store_id IN (2, 3, 6)), reconciled AS (SELECT s.* FROM store_sales s INNER JOIN remaining_keys k ON s.product_id = k.product_id) SELECT DATE_TRUNC('MONTH', sale_date) AS activity_month, DATE_TRUNC('WEEK', sale_date) AS week_start, CASE WHEN revenue >= 3800 THEN 'PREMIUM' ELSE 'STANDARD' END AS revenue_tier, APPROX_PERCENTILE(revenue, ARRAY(0.25, 0.5, 0.75)) AS revenue_quartiles, BIT_AND(units) AS units_bit_and, APPROX_PERCENTILE(revenue, 0.5) AS revenue_p50, APPROX_PERCENTILE(units, 0.95) AS units_p95, COUNT(DISTINCT product_id) AS distinct_product_ids, STDDEV_SAMP(units) AS units_stddev FROM reconciled GROUP BY DATE_TRUNC('MONTH', sale_date), DATE_TRUNC('WEEK', sale_date), CASE WHEN revenue >= 3800 THEN 'PREMIUM' ELSE 'STANDARD' END
